    /** Visitor handles custom elements with nested content */
    public function test_visitor_custom_element_with_nesting(): void
    {
        $visitor = new class {
            public function visit_custom_element(...$args)
            {
                return ['custom' => '[CUSTOM WIDGET]'];
            }
        };
        $options = \HtmlToMarkdown\ConversionOptions::from_json('{}');
        $visitorHandle = \HtmlToMarkdown\VisitorHandle::from_php_object($visitor);
        $options = $options->withVisitor($visitorHandle);
        $result = HtmlToMarkdown::convert(
            '<div><custom-widget data-value="123"><p>Widget content here</p><span>With nested elements</span></custom-widget></div>',
            $options,
        );

        $this->assertStringContainsString('[CUSTOM WIDGET]', $result->content ?? null);
        $this->assertStringNotContainsString('Widget content here', $result->content ?? null);
    }

